def bracket_partners(formula):
    stack = []
    pairs = []
    for i, ch in enumerate(formula):
        if ch in '([{':
            stack.append(i)
        elif ch in ')]}':
            pairs.append((stack.pop(), i))
    pairs.sort()
    return pairs
